package io.joshuasalcedo.swaswa.ui.collection;

import io.joshuasalcedo.swaswa.html.PageScript;
import io.joshuasalcedo.swaswa.react.ReactElement;
import io.joshuasalcedo.swaswa.ui.Ui;
import java.util.List;
import java.util.function.Consumer;

/**
 * swaswa-ui's {@code DataMap} (data-map.tsx), a real React component, from Java: create it, set it, add it.
 * Generated by swaswa-react java-gen from its TypeScript props: do not edit.
 */
public final class UiDataMap extends ReactElement<UiDataMap> {

    /** A UiDataMap. */
    public UiDataMap() {
        super("DataMap", false);
    }

    /** {@code value}. The map: values are text, numbers, yes/no, null, lists and maps. */
    public UiDataMap setValue(Record value) {
        return prop("value", value);
    }

    /** Told when it calls {@code onEdit}, with what it calls it with. Values (not maps or lists) edited in place: the path and what was typed, as JSON when it reads as JSON. */
    public UiDataMap onEdit(Consumer<String> listener) {
        return onEvent("onEdit", e -> listener.accept(e.payload(String.class)));
    }

    /** Told when it calls {@code onAdd}, with what it calls it with. An entry added at the top level. */
    public UiDataMap onAdd(Consumer<String> listener) {
        return onEvent("onAdd", e -> listener.accept(e.payload(String.class)));
    }

    /** Told when it calls {@code onRemove}, with what it calls it with. An entry removed (any depth). */
    public UiDataMap onRemove(Consumer<String> listener) {
        return onEvent("onRemove", e -> listener.accept(e.payload(String.class)));
    }

    /** {@code depth}. How deep the map is open at first (1: the top level). */
    public UiDataMap setDepth(double value) {
        return prop("depth", value);
    }

    public Double getDepth() {
        return getProp("depth", Double.class);
    }

    @Override
    protected List<PageScript> libraries() {
        return List.of(Ui.bundle());
    }
}
